test({ sr: 'poravnava ugnježdene nizove', en: 'flattens nested arrays' }, () => {
  expect(flatten([1, [2, [3, [4]]]])).toEqual([1, 2, 3, 4]);
});
test({ sr: 'prazni nizovi nestaju', en: 'empty arrays disappear' }, () => {
  expect(flatten([[], [[]]])).toEqual([]);
});
test({ sr: 'prazan niz daje prazan niz', en: 'an empty array gives an empty array' }, () => {
  expect(flatten([])).toEqual([]);
});

hiddenTests:
test('already flat arrays stay the same', () => {
  expect(flatten([1, 2, 3])).toEqual([1, 2, 3]);
});
test('does not change the input', () => {
  const input = [1, [2, [3]]];
  flatten(input);
  expect(input).toEqual([1, [2, [3]]]);
});
test('strings and objects are not flattened', () => {
  expect(flatten(['ab', [{ a: 1 }, ['c']]])).toEqual(['ab', { a: 1 }, 'c']);
});
test('very deep nesting', () => {
  let nested = [0];
  for (let i = 1; i <= 200; i++) nested = [i, nested];
  expect(flatten(nested)).toHaveLength(201);
});

